/**
 * NTI-skolans prövningsomgång hösten 2026 i Stockholmsregionen.
 *
 * Anordnaren har gått över till ett enda ansökningstillfälle per halvår. Det
 * öppnade 17 augusti och stängde 20 augusti, och den som antagits tilldelas en
 * prövningsperiod någon gång mellan 14 september och 30 oktober. Datan sa
 * tidigare bara "ansökan öppnar 17 augusti", vilket slutade vara sant elva
 * dagar senare — en gången omgång ska synas som en gången omgång, med den
 * publicerade prövningsperioden kvar, eftersom den är svaret på frågan "hann
 * jag?".
 */
function ntiAutumn2026(): NextPeriod {
  return {
    label:
      'Ansökan till hösten 2026 var öppen 17–20 augusti och är stängd. Du som antagits tilldelas ' +
      'en prövningsperiod någon gång mellan 14 september och 30 oktober, med ett slutprov på ' +
      'plats i Stockholm som inte går att boka om. Nästa ansökan gäller vårterminen 2027 och ' +
      'datumen publiceras på anordnarens sida under hösten 2026.',
    applicationStart: '2026-08-17',
    applicationEnd: '2026-08-20',
    examWindowStart: '2026-09-14',
    examWindowEnd: '2026-10-30',
    confirmed: true,
    nextChance: {
      note: 'Nästa ansökan gäller vårterminen 2027; NTI-skolan publicerar datumen under hösten.',
    },
  };
}

